import json
import math

# Derivation from the givens (exact integer algebra):
# cos x + sin x = 1/2  =>  1 + 2 sin x cos x = 1/4  =>  sin x cos x = -3/8.
# With t = tan x: 2t/(1+t^2) = -3/4  =>  3t^2 + 8t + 3 = 0.
A_COEF, B_COEF, C_COEF = 3, 8, 3
disc = B_COEF * B_COEF - 4 * A_COEF * C_COEF  # 28
roots = [(-B_COEF + math.sqrt(disc)) / (2 * A_COEF),
         (-B_COEF - math.sqrt(disc)) / (2 * A_COEF)]

# Domain filter: 0 < x < 180 deg with tan x = r means x = 180 deg + atan(r) in (90, 180).
valid = []
for r in roots:
    x = math.pi + math.atan(r)
    if 0 < x < math.pi and math.isclose(math.cos(x) + math.sin(x), 0.5, abs_tol=1e-9):
        valid.append((r, math.degrees(x)))

def is_squarefree(n):
    d = 2
    while d * d <= n:
        if n % (d * d) == 0:
            return False
        d += 1
    return True

# Exhaustive search for tan x = -(a + sqrt(b)) / c with positive integers,
# b squarefree, gcd(a, b, c) = 1, a, c up to 200.
matches = []
if valid:
    r = valid[0][0]
    for c in range(1, 201):
        for a in range(1, 201):
            needed = -r * c - a  # required sqrt(b)
            if needed <= 0:
                continue
            b = round(needed * needed)
            if b <= 0 or not math.isclose(math.sqrt(b), needed, abs_tol=1e-9):
                continue
            if not is_squarefree(b):
                continue
            if math.gcd(math.gcd(a, b), c) != 1:
                continue
            matches.append((a, b, c))

if len(valid) == 1 and len(matches) == 1:
    a, b, c = matches[0]
    result = {
        "final_answer": str(a + b + c),
        "evidence": {
            "sin_cos_product": -3 / 8,
            "tan_quadratic": "3t^2+8t+3=0",
            "valid_tan_root": valid[0][0],
            "valid_angle_deg": round(valid[0][1], 6),
            "a": a, "b": b, "c": c,
            "match_count": len(matches),
        },
    }
else:
    result = {
        "final_answer": "UNSUPPORTED",
        "evidence": {"valid_roots": len(valid), "matches": len(matches)},
    }

print(json.dumps(result))
